-- Conteúdo das páginas "Saiba mais" importado da página Captação do Notion em 05/11/2026.
-- A descrição recebe o texto completo enviado pelo palestrante, quando existe; o resumo do topo fica vazio para não repetir o texto.
-- Fotos publicadas com o site em /fotos/. Bios ainda não enviadas ficam vazias.
begin;
update public.activities set speaker_name=$c$Ronaldo Vieira, Khiara Shantala, Gabriel Marinho e Lucas Amorim$c$, speaker_bio=$c$$c$, speaker_photo_url=$c$/fotos/mesa-redonda.webp$c$, starts_at=timestamptz '2026-11-03 09:30:00-03', ends_at=timestamptz '2026-11-03 10:30:00-03', speaker_socials='{}'::jsonb, content_revision=content_revision+1, content_updated_at=clock_timestamp()
  where id='mesa-redonda' and event_date=date '2026-11-03';
update public.activities set description=$c$A palestra “Trabalhando com Dados nos Dias Atuais” busca apresentar as principais funções, ferramentas e o dia a dia da área de Dados.
Mostra como múltiplas ferramentas de integrações, data lake e data viz se conectam no dia a dia.
Três casos reais ilustram os desafios de criar um data lake, migrar um banco de dados e estruturar modelos de dados agênticos para dados corporativos.
Ao final, haverá espaço para perguntas sobre carreira e sobre os temas abordados.$c$, speaker_name=$c$Lucas Neres · Head de Dados & Analytics na FENG$c$, speaker_bio=$c$Head de Dados & Analytics na Feng, liderando equipes, construção de plataformas modernas de dados e produtos. Atuo junto à área de Negócio há mais de 8 anos, auxiliando na estratégia de monetização de dados e aplicando metodologias avançadas de BI, DBA, Data Science e Inteligência Artificial para solucionar desafios.$c$, speaker_photo_url=$c$/fotos/trabalhando-com-dados.webp$c$, starts_at=timestamptz '2026-11-03 11:00:00-03', ends_at=timestamptz '2026-11-03 12:00:00-03', speaker_socials='{}'::jsonb, content_revision=content_revision+1, content_updated_at=clock_timestamp()
  where id='trabalhando-com-dados' and event_date=date '2026-11-03';
update public.activities set description=$c$O workshop apresentará a experiência da Casa da Inovação Ziraldo como equipamento público de educação tecnológica e inovação, destacando o papel das políticas públicas na democratização do acesso à tecnologia e na construção de novas oportunidades.
Conduzido pelo instrutor sênior Vitor Mello, o encontro abordará a atuação da Casa, suas práticas de formação tecnológica e as possibilidades de aplicação da Inteligência Artificial na educação, no desenvolvimento de projetos e na transformação social.
A programação contará também com a participação de alguns alunos que compartilharão suas experiências como cases de sucesso na área de tecnologia e desenvolvimento de sites, demonstrando como o acesso ao conhecimento e à formação tecnológica pode transformar ideias em projetos reais.$c$, speaker_name=$c$Casa da Inovação Ziraldo$c$, speaker_bio=$c$A Casa da Inovação Ziraldo é um equipamento público de educação tecnológica e inovação do município de Queimados, vinculado à Secretaria Municipal de Projetos e Estratégias (SEPEC), desenvolvido em parceria com o Instituto Vielas.
Por meio de cursos livres e oficinas, atende diferentes gerações, desde crianças a partir dos 8 anos até idosos, oferecendo formação em áreas como introdução à robótica, programação, criação de games, social media, desenvolvimento de aplicativos e inteligência artificial.
A iniciativa fortalece as políticas públicas de inclusão digital e democratização do acesso à tecnologia, ampliando oportunidades e estimulando o protagonismo e a transformação social.$c$, speaker_photo_url=$c$/fotos/tecnologia-ia-oportunidades.webp$c$, starts_at=timestamptz '2026-11-03 14:00:00-03', ends_at=timestamptz '2026-11-03 15:10:00-03', speaker_socials='{}'::jsonb, content_revision=content_revision+1, content_updated_at=clock_timestamp()
  where id='tecnologia-ia-oportunidades' and event_date=date '2026-11-03';
update public.activities set speaker_name=$c$Raul Nascimento, Dirceu Silvestre, Machado e Leonardo$c$, speaker_bio=$c$Raul Nascimento — RAG em Redes Sociais Federadas para o Acesso à Informação em Universidades Públicas
Hoje boa parte da comunicação da comunidade acadêmica passa por redes sociais de grandes empresas, sem controle da universidade sobre os próprios dados. A IC parte da ideia de uma rede social federada da própria instituição e foca num agente conversacional (RAG) que responde, dentro da rede, perguntas sobre informações públicas da UFRRJ, com dados coletados do SIGAA e modelos rodando localmente. Comparei três abordagens de busca e mostrei que um agente que escolhe sozinho entre busca semântica e consulta a um banco estruturado resolve tanto perguntas abertas quanto perguntas de contagem e listagem, que é onde o RAG tradicional falha. Orientação do Prof. Marcel William Rocha da Silva.

Dirceu Silvestre
"Pesquisar é bom, bom, Pesquisar é bom, bom, bom. Bota a mão na cabeça que vamos pensar..." Como tropeços me fizeram chegar ao pódio de uma Olimpíada de Direito e por que aplicar o método científico é o primeiro passo para validar sua ideia antes de criar o próximo unicórnio.

Machado — Redes Complexas
Estudantes de cursos diferentes realmente colaboram no campus? Na minha IC, uso Redes Complexas para mapear essas conexões na UFRRJ de Nova Iguaçu e embasar o UniHub, que transforma conexões sociais em projetos interdisciplinares.$c$, speaker_photo_url=$c$/fotos/iniciacao-cientifica.webp$c$, starts_at=timestamptz '2026-11-03 15:20:00-03', ends_at=timestamptz '2026-11-03 16:00:00-03', speaker_socials='{}'::jsonb, content_revision=content_revision+1, content_updated_at=clock_timestamp()
  where id='iniciacao-cientifica' and event_date=date '2026-11-03';
update public.activities set description=$c$Uma conversa leve e prática sobre LinkedIn, currículo, entrevistas e empregabilidade em Tecnologia. Vamos explorar como valorizar competências, conquistar oportunidades e utilizar a Inteligência Artificial de forma estratégica, tanto na preparação para processos seletivos quanto na atuação profissional, conhecendo as novas habilidades e expectativas do mercado de trabalho.$c$, speaker_name=$c$Barbara Nery · Gerente de Operações de TI na CSP Tech$c$, speaker_bio=$c$Gerente de Operações de TI na CSP Tech, com mais de 20 anos de experiência em tecnologia. Lidera iniciativas de transformação digital, inovação e desenvolvimento de pessoas. Professora, palestrante e mentora, conecta tecnologia, educação, mercado e inclusão.$c$, speaker_photo_url=$c$/fotos/linkedin-curriculo-entrevista.webp$c$, starts_at=timestamptz '2026-11-03 16:00:00-03', ends_at=timestamptz '2026-11-03 17:00:00-03', speaker_socials='{}'::jsonb, content_revision=content_revision+1, content_updated_at=clock_timestamp()
  where id='linkedin-curriculo-entrevista' and event_date=date '2026-11-03';
update public.activities set speaker_name=$c$Fellipe Bravo · Senior Software Engineer na Neo Financial$c$, speaker_bio=$c$Fellipe Bravo é formado em Ciência da Computação pela UFRRJ e possui mais de 8 anos de experiência em engenharia de software, com atuação em desenvolvimento mobile, blockchain e liderança técnica. Trabalhou com empresas brasileiras e internacionais e atualmente atua como Senior Software Engineer na Neo Financial, em Calgary, no Canadá.$c$, speaker_photo_url=$c$/fotos/da-rural-ao-canada.webp$c$, starts_at=timestamptz '2026-11-04 16:30:00-03', ends_at=timestamptz '2026-11-04 17:30:00-03', speaker_socials='{}'::jsonb, content_revision=content_revision+1, content_updated_at=clock_timestamp()
  where id='da-rural-ao-canada' and event_date=date '2026-11-04';
update public.activities set description=$c$Com mais de 200 serviços disponíveis, entrar no universo da AWS pode parecer um jogo de mundo aberto: existem diferentes caminhos, desafios, ferramentas e possibilidades, mas nem sempre é fácil descobrir por onde começar.
Nesta palestra, vamos explorar a AWS de uma maneira divertida e acessível, usando analogias com o universo dos games. Vamos conhecer os diferentes estilos de jogadores, entender como escolher seu personagem, descobrir os principais serviços e aprender a montar seu inventário para enfrentar os primeiros desafios no Cloud Computing.$c$, speaker_name=$c$Paloma Lataliza · Cloud Engineer na Caylent e AWS Hero$c$, speaker_bio=$c$Cloud Engineer e DevOps Specialist. Foi reconhecida pela AWS como uma AWS Hero. Lidera o AWS User Groups Mi, co-fundei o projeto Mulheres na Nuvem MG, e organizo eventos como o AWSome Women Community Summit Brasil e o DevOpsDays BH.$c$, speaker_photo_url=$c$/fotos/e-se-a-aws-fosse-um-jogo.webp$c$, starts_at=timestamptz '2026-11-06 18:00:00-03', ends_at=timestamptz '2026-11-06 19:00:00-03', speaker_socials='{}'::jsonb, content_revision=content_revision+1, content_updated_at=clock_timestamp()
  where id='e-se-a-aws-fosse-um-jogo' and event_date=date '2026-11-06';
update public.activities set description=$c$Durante o workshop, serão apresentados mini projetos desenvolvidos pelo Meninas na Robótica, como o carrinho Bluetooth e o copo de flores. Por meio dessas atividades, o público poderá conhecer um pouco do trabalho realizado pelo grupo e perceber como a criatividade, a experimentação e a tecnologia podem caminhar juntas. A proposta é despertar a curiosidade, incentivar o interesse pela robótica e mostrar, principalmente às meninas, que esse espaço também pertence a elas. Duas sessões: 09:30 e 11:00.$c$, speaker_name=$c$Meninas na Robótica · CEFET$c$, speaker_bio=$c$O Meninas na Robótica é um projeto que busca aproximar meninas do universo da robótica, da ciência e da tecnologia, incentivando a participação feminina nessas áreas desde a escola. Por meio de oficinas, capacitações e atividades práticas, o projeto proporciona oportunidades de aprendizado, troca de experiências e desenvolvimento de habilidades, mostrando às meninas que elas também podem criar, programar e desenvolver soluções tecnológicas.$c$, speaker_photo_url=$c$/fotos/meninas-na-robotica.webp$c$, starts_at=timestamptz '2026-11-05 09:30:00-03', ends_at=timestamptz '2026-11-05 12:00:00-03', speaker_socials='{}'::jsonb, content_revision=content_revision+1, content_updated_at=clock_timestamp()
  where id='meninas-na-robotica' and event_date=date '2026-11-05';
update public.activities set speaker_name=$c$Equipe SHIELD NIG · Escola Firjan SESI Nova Iguaçu$c$, speaker_bio=$c$Fundada em 2017 no ensino médio da Escola Firjan SESI Nova Iguaçu (RJ). O nome une a inspiração na Marvel (Shield: união e solução de problemas) ao município de Nova Iguaçu (Nig). Seu mascote é o lobo-guará, simbolizando coragem, sabedoria e espírito de alcateia.
A equipe busca transformar a realidade local e popularizar a ciência e a tecnologia por meio de inovação, dados, respeito, cooperação, resiliência e aprendizado prático.
Principais conquistas no Torneio Brasil de Robótica: 1º lugar em Mérito Científico (2017); 1º lugar geral estadual (RJ) e 2º lugar geral nacional (2024); 3º lugar geral estadual (2025).
O impacto vai além dos torneios, promovendo o desenvolvimento socioemocional e a formação integral dos jovens.$c$, speaker_photo_url=$c$/fotos/equipe-robotica-shield-nig.webp$c$, starts_at=timestamptz '2026-11-05 14:00:00-03', ends_at=timestamptz '2026-11-05 15:30:00-03', speaker_socials='{"instagram": "https://www.instagram.com/shield_nig", "website": "https://shieldnig.blogspot.com/"}'::jsonb, content_revision=content_revision+1, content_updated_at=clock_timestamp()
  where id='equipe-robotica-shield-nig' and event_date=date '2026-11-05';
update public.activities set speaker_name=$c$Khiara Shantala · Co-founder da Visão Urbana$c$, speaker_bio=$c$Cientista da computação com ênfase em engenharia de software e computação de alto desempenho pela UFRRJ, cientista de dados, analista de inovação e Co-founder da Visão Urbana, startup de visão computacional. Integro a Secretaria Municipal de Ciência, Tecnologia e Inovação do Rio de Janeiro, onde conecto a parte analítica dos dados à estratégia e auxilio na governança de grandes projetos públicos que envolvem tecnologia, IA, ciência e inovação.
Minha missão é construir conexões sólidas entre o ecossistema de tecnologia, inteligência artificial e a cidade do Rio.$c$, speaker_photo_url=$c$/fotos/sua-ideia-vale-uma-startup.webp$c$, starts_at=timestamptz '2026-11-05 16:00:00-03', ends_at=timestamptz '2026-11-05 17:00:00-03', speaker_socials='{}'::jsonb, content_revision=content_revision+1, content_updated_at=clock_timestamp()
  where id='sua-ideia-vale-uma-startup' and event_date=date '2026-11-05';
update public.activities set description=$c$O erro número 1 é chamar modelos de forma direta. Venha conhecer esse padrão e entender como os AI Gateways resolvem esse problema.$c$, speaker_name=$c$Davi Piala · Technical Account Manager na Google$c$, speaker_bio=$c$Technical account manager na Google, com experiência em grandes empresas como Amazon e Oracle. Antigo Dev, antigo Arquiteto de Software e nem um pouco novo na área e na data de nascimento, com cerca de 20 anos de experiência e muito foco em integração.$c$, speaker_photo_url=$c$/fotos/visao-sobre-ai-gateway.webp$c$, starts_at=timestamptz '2026-11-05 18:00:00-03', ends_at=timestamptz '2026-11-05 19:00:00-03', speaker_socials='{}'::jsonb, content_revision=content_revision+1, content_updated_at=clock_timestamp()
  where id='visao-sobre-ai-gateway' and event_date=date '2026-11-05';
update public.activities set description=$c$Como a Ciência da Computação pode fazer a diferença em empresas cujo negócio principal não é desenvolver software?
A partir de sua trajetória, da iniciação científica na UFRRJ aos projetos de inovação na TIM, Kevyn compartilhará experiências sobre a entrada no mercado de trabalho, a importância das oportunidades acadêmicas e os desafios de atuar como desenvolvedor em um setor multidisciplinar. A palestra abordará como os conhecimentos adquiridos na graduação podem ser aplicados à automação, à inovação e à resolução de problemas reais, mostrando que as possibilidades de atuação de um cientista da computação vão muito além das empresas de tecnologia.$c$, speaker_name=$c$Kevyn Carvalho de Souza · Desenvolvedor e Analista na TIM Brasil$c$, speaker_bio=$c$Kevyn Carvalho de Souza é bacharel em Ciência da Computação pela Universidade Federal Rural do Rio de Janeiro (UFRRJ) e atua como Desenvolvedor e Analista na TIM Brasil, com foco em desenvolvimento de software, automação e inovação tecnológica. Iniciou sua trajetória na iniciação científica, ainda durante a graduação, e acumulou experiências profissionais na DATAPREV, Italtel e TIM. Atualmente, é responsável pelo Portal do Laboratório da TIM e participa de projetos de Pesquisa e Desenvolvimento (P&D), criando soluções digitais e explorando novas tecnologias para enfrentar desafios do setor de telecomunicações.$c$, speaker_photo_url=$c$/fotos/ciencia-computacao-alem-software.webp$c$, starts_at=timestamptz '2026-11-06 09:30:00-03', ends_at=timestamptz '2026-11-06 10:30:00-03', speaker_socials='{}'::jsonb, content_revision=content_revision+1, content_updated_at=clock_timestamp()
  where id='ciencia-computacao-alem-software' and event_date=date '2026-11-06';
update public.activities set description=$c$Entenda como o Apache Kafka funciona por dentro e quais padrões, como Outbox, idempotência e Saga, tornam sistemas orientados a eventos confiáveis.$c$, speaker_name=$c$Hugo Machado · Analista de Desenvolvimento Sênior na Bemobi$c$, speaker_bio=$c$Analista de Desenvolvimento Sênior na Bemobi, onde há 8 anos desenvolve sistemas de pagamento em larga escala. Hoje trabalha na plataforma de recorrência da empresa, construída sobre arquitetura orientada a eventos. Formado em Ciência da Computação pela PUC-Rio, tem experiência em arquitetura de microsserviços, cloud e observabilidade.$c$, speaker_photo_url=$c$/fotos/kafka-alem-das-filas.webp$c$, starts_at=timestamptz '2026-11-06 11:00:00-03', ends_at=timestamptz '2026-11-06 12:00:00-03', speaker_socials='{}'::jsonb, content_revision=content_revision+1, content_updated_at=clock_timestamp()
  where id='kafka-alem-das-filas' and event_date=date '2026-11-06';
update public.activities set description=$c$LLMs já estão em produção, mas poucos times sabem como eles quebram. Nesta palestra, você vai entender o que muda na superfície de ataque, conhecer as principais ameaças a apps e agentes com IA e como se defender delas. Também vai sair com um caminho prático para começar na área: roadmap, labs, leituras e carreira.$c$, speaker_name=$c$Michelle Mesquita · AI Security Engineer no iFood$c$, speaker_bio=$c$Michelle é AI Security Engineer no iFood e doutoranda em Informática no PPGI-UNIRIO, onde pesquisa o hardening de código gerado por LLMs. Também é professora de segurança na PUC-PR. É formada em Engenharia de Computação (UVA), mestre em Engenharia Biomédica (COPPE/UFRJ) e tem MBA em Cybersecurity (FIAP). Escreve sobre segurança e IA no Medium e compartilha projetos no GitHub como @michelleamesquita.$c$, speaker_photo_url=$c$/fotos/como-iniciar-em-ia-security.webp$c$, starts_at=timestamptz '2026-11-06 14:00:00-03', ends_at=timestamptz '2026-11-06 15:30:00-03', speaker_socials='{"website": "https://github.com/michelleamesquita"}'::jsonb, content_revision=content_revision+1, content_updated_at=clock_timestamp()
  where id='como-iniciar-em-ia-security' and event_date=date '2026-11-06';
update public.activities set speaker_name=$c$$c$, speaker_bio=$c$$c$, speaker_photo_url=null, starts_at=timestamptz '2026-11-06 16:00:00-03', ends_at=timestamptz '2026-11-06 17:00:00-03', speaker_socials='{}'::jsonb, content_revision=content_revision+1, content_updated_at=clock_timestamp()
  where id='como-e-desenvolver-um-jogo' and event_date=date '2026-11-06';
