  where id in ('mesa-redonda','trabalhando-com-dados','tecnologia-ia-oportunidades','iniciacao-cientifica','linkedin-curriculo-entrevista','da-rural-ao-canada','e-se-a-aws-fosse-um-jogo','meninas-na-robotica','equipe-robotica-shield-nig','sua-ideia-vale-uma-startup','visao-sobre-ai-gateway','ciencia-computacao-alem-software','kafka-alem-das-filas','como-iniciar-em-ia-security','como-e-desenvolver-um-jogo');
do $$
begin
  -- Num banco recém-criado o catálogo só entra depois, pelo seed; aqui só se cobra o que já existe.
  if exists(select 1 from public.activities where content_updated_at is null and id in ('mesa-redonda','trabalhando-com-dados','tecnologia-ia-oportunidades','iniciacao-cientifica','linkedin-curriculo-entrevista','da-rural-ao-canada','e-se-a-aws-fosse-um-jogo','meninas-na-robotica','equipe-robotica-shield-nig','sua-ideia-vale-uma-startup','visao-sobre-ai-gateway','ciencia-computacao-alem-software','kafka-alem-das-filas','como-iniciar-em-ia-security','como-e-desenvolver-um-jogo')) then
